def name_operands(region,address,operation):
    operation=offset_names(region,address,operation)
    if (region,address)!=('Action',0xE5A0):return operation
    for delta,field in ((5,'Components.Component2.High'),(3,'Components.Component1.High'),(1,'Components.Component0.High')):
        operation=operation.replace('(IY+#'+format(delta,'02X')+')','(IY+FActionRecord.'+field+')')
    for before,after in (('(#9B82)','(@ActionParameterActivationState.UnknownByte1)'),
        ('(#E644)','(@ActionRecordUpdateState.WarningLatch)'),('LD A, #7D','LD A, @ActionRecordUpdateConst.LimitBias'),
        ('CP #80','CP @ActionReuseConst.ReusableHigh'),('LD D, #12','LD D, @ActionCloseRecordConst.TransferClass'),
        ('CP #08','CP @ActionRecordUpdateConst.NearLimit'),('LD A, #80','LD A, @ActionRecordUpdateConst.WarningArmed'),
        ('LD A, #18','LD A, @ActionRecordUpdateConst.WarningSent'),('#F3B9','@ActionRecordUpdateConst.DockingText')):
        operation=operation.replace(before,after)
    return operation


def qualify_mutations(records,regions,functions):
    for item in records:
        if item['region']!='Action' or item['target'] not in (0xE5B0,0xE5CF,0xE5EA,0xE644):continue
        item.update(target_region='Action',target_bank=0,target_slot=17,target_offset=item['target']-0x6000,
            target_source_classified=True,target_path='Source/Action/UpdateRecordComponents.asm')
        if 0xE5A0<=item['writer']<0xE655:
            item.update(writer_bank=0,writer_offset=item['writer']-0x6000,writer_source_classified=True)
